from typing import List

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # Iterate through all possible starting positions 'a' for the first subarray.
        # The first subarray is nums[a : a + k] and the second is nums[a + k : a + 2 * k].
        # The loop runs for 'a' from 0 to n - 2*k.
        # If n < 2*k, the range will be empty, and the function returns False.
        for a in range(n - 2 * k + 1):
            # Check if the first subarray is strictly increasing
            first_inc = True
            for i in range(a, a + k - 1):
                if nums[i] >= nums[i + 1]:
                    first_inc = False
                    break
            if not first_inc:
                continue

            # Check if the second subarray is strictly increasing
            second_inc = True
            for i in range(a + k, a + 2 * k - 1):
                if nums[i] >= nums[i + 1]:
                    second_inc = False
                    break

            if first_inc and second_inc:
                return True

        return False
